insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('SG:software-developer','2026-08-11',0,0,0,0,15,0,0,0,3,18,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 maps the broad software-development scope directly to 25121 Software developer, while web/mobile, DevOps, AI/ML and other specialised roles have separate codes.','entry_level_basis','Computer science, software engineering and related computing degrees are common routes; fifteen approved Singapore programmes are retained as related study pathways because the reviewed staging relation is common_pathway rather than direct occupational qualification.','qualification_note','There is no universal statutory occupational licence required to work as a Software Developer in Singapore.','market_scope','No exact comparable shortage, vacancy, earnings or growth series is scored in this foundation phase.','visa_scope','No occupation-specific visa credit is assigned in this foundation phase.'),'2026-08-11'),
('SG:data-analyst','2026-08-11',0,0,0,0,10,0,0,0,5,15,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 maps Statistical officer/Data analyst directly to 21231, distinct from 21222 Data scientist and ICT business analyst 25112.','entry_level_basis','Analytics, data science, statistics, economics and quantitative business study are relevant routes; ten approved programmes are retained as related pathways.','qualification_note','There is no universal statutory occupational licence required to work as a Data Analyst in Singapore.','market_scope','Classification evidence is not converted into demand or salary points until the later comparable market-data phase.','visa_scope','No occupation-specific visa credit is assigned in this foundation phase.'),'2026-08-11'),
('SG:data-engineer','2026-08-11',0,0,0,0,10,0,0,0,5,15,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 provides the direct five-digit occupation 25213 Data engineer, separated from database administration and architecture.','entry_level_basis','Data, computing and engineering degrees can support entry, but production data-platform roles often expect database, programming, cloud and pipeline experience; five approved programmes are retained as related pathways.','qualification_note','There is no universal statutory occupational licence required to work as a Data Engineer in Singapore.','market_scope','No exact shortage, vacancy, earnings or growth component is assigned in the foundation phase.','visa_scope','No occupation-specific visa credit is assigned in this foundation phase.'),'2026-08-11'),
('SG:cybersecurity-analyst','2026-08-11',0,0,0,0,10,0,0,0,3,13,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 does not publish one generic Cybersecurity Analyst five-digit code. The canonical analyst scope crosses 25241 Cyber risk specialist, 25243 Security operations specialist, 25246 Cyber incident investigation specialist, 25247 Threat analysis specialist and 25249 Cybersecurity professional n.e.c.','entry_level_basis','Information-security and cybersecurity degrees provide structured entry; two approved Singapore information-security programmes are retained as direct academic pathways, but study does not itself constitute a professional licence.','qualification_note','There is no universal personal occupational licence for every Cybersecurity Analyst. Under the Cybersecurity Act, CSA separately licenses providers of specified services, currently penetration testing and managed SOC monitoring; that provider-service regime is not attributed to every employee analyst role.','market_scope','The multi-code analyst scope is kept explicit and is not collapsed into an unsupported exact labour-market series.','visa_scope','No occupation-specific visa credit is assigned in this foundation phase.'),'2026-08-11'),
('SG:network-administrator','2026-08-11',0,0,0,0,15,0,0,0,3,18,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 maps network, server, applications and computer-systems administration to 25220, providing a direct operational infrastructure anchor for the canonical Network Administrator.','entry_level_basis','Computing, computer engineering and information-systems study plus practical network and systems administration skills provide common routes; five approved programmes are retained as related pathways.','qualification_note','There is no universal statutory occupational licence required to work as a Network Administrator in Singapore. Telecommunications or service-provider licences regulate organisations and services rather than this general employee occupation.','market_scope','No exact comparable market components are scored at foundation stage.','visa_scope','No occupation-specific visa credit is assigned in this foundation phase.'),'2026-08-11'),
('SG:cloud-engineer','2026-08-11',0,0,0,0,10,0,0,0,3,13,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 provides 25231 Cloud specialist as the direct cloud-platform occupation anchor, while DevOps engineer remains separately classified at 25125.','entry_level_basis','Computer science, software engineering and ICT degrees can lead toward cloud work, but production cloud roles commonly require operating-system, networking, automation, security and platform experience; ten approved programmes are related pathways.','qualification_note','There is no universal statutory occupational licence required for Cloud Engineers. Cloud-provider certifications and the MTCS organisational certification scheme are not personal licences to practise this occupation.','market_scope','No exact comparable shortage, vacancy, salary or growth evidence is scored in SG v1 foundation.','visa_scope','No occupation-specific visa credit is assigned in this foundation phase.'),'2026-08-11'),
('SG:database-administrator','2026-08-11',0,0,0,0,12,0,0,0,3,15,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 maps Data/Database administrator directly to 25211 and keeps database architecture at 25212 and data engineering at 25213.','entry_level_basis','Computer science, information systems and ICT study can support entry, while dedicated DBA roles commonly value SQL, database operations, backup, recovery and systems experience; eight approved programmes are retained as related pathways.','qualification_note','There is no universal statutory occupational licence required to work as a Database Administrator in Singapore.','market_scope','No exact comparable market components are assigned in the foundation phase.','visa_scope','No occupation-specific visa credit is assigned in this foundation phase.'),'2026-08-11'),
('SG:ict-support-technician','2026-08-11',0,0,0,0,15,0,0,0,5,20,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 directly identifies 35123 IT support technician, distinct from IT infrastructure technician 35121 and IT security technician 35122.','entry_level_basis','ICT diplomas, computing qualifications, vendor training and practical troubleshooting experience are common entry routes; five approved degree programmes are retained as related rather than direct technician qualifications.','qualification_note','There is no universal statutory occupational licence required to work as an IT Support Technician in Singapore.','market_scope','No exact comparable shortage, vacancy, earnings or growth series is scored in this foundation phase.','visa_scope','No occupation-specific visa credit is assigned in this foundation phase.'),'2026-08-11')
